"use strict";
const{test}=require("node:test"),S=require("./support.cjs"),{assert}=S;
test("two independent managed instances contend and exact owned release permits reopen",async t=>{const f=await S.fixture(t),other=S.api.createTransactionalApplicationStore(f.cfg);await assert.rejects(other.open({version:1}),{code:"LOCK_HELD"});await f.store.close();await other.open({version:1});await other.close();await f.store.open({version:1});});
for(const kind of ["relative","temp","missing","file","nonempty"])test("explicit root admission rejects "+kind,async()=>{let root=await S.root();if(kind==="relative")root="relative";if(kind==="temp")root=S.os.tmpdir();if(kind==="missing")root=S.path.join(root,"missing");if(kind==="file"){root=S.path.join(root,"file");await S.fs.writeFile(root,"x");}if(kind==="nonempty")await S.fs.writeFile(S.path.join(root,"extra"),"x");const store=S.api.createTransactionalApplicationStore(S.config(root));await assert.rejects(store.create({version:1,data:{},allowedScopes:[{field:"folderUi",dependencies:[]}]}));await store.close();});
test("opening absent data never initializes it",async()=>{const root=await S.root(),store=S.api.createTransactionalApplicationStore(S.config(root));await assert.rejects(store.open({version:1}));assert.deepEqual(await S.fs.readdir(root),[]);});
test("wrong application context and authority reject existing profile",async t=>{const f=await S.fixture(t);await f.store.close();for(const cfg of [{...f.cfg,applicationContextId:"different"},{...f.cfg,authorityId:S.crypto.randomUUID()}]){const other=S.api.createTransactionalApplicationStore(cfg);await assert.rejects(other.open({version:1}));await other.close();}});
test("unknown lock is not removed or replaced",async()=>{const root=await S.root(),file=S.path.join(root,"APPLICATION.lock");await S.fs.writeFile(file,"unknown-owner");const store=S.api.createTransactionalApplicationStore(S.config(root));await assert.rejects(store.open({version:1}),{code:"LOCK_HELD"});await store.close();assert.equal(await S.fs.readFile(file,"utf8"),"unknown-owner");});
test("token substitution fences stale owner and close refuses unknown ownership",async t=>{const f=await S.fixture(t),q=S.request(f,await S.read(f)),lock=S.path.join(f.directory,"APPLICATION.lock"),raw=await S.fs.readFile(lock,"utf8"),other=JSON.parse(raw);other.token=S.crypto.randomUUID();await S.fs.writeFile(lock,S.C.canonical(other)+"\n");assert.equal((await f.store.transact(q)).code,"LEASE_LOST");await assert.rejects(f.store.close());assert.equal((await S.disk(f)).revision,0);await S.fs.writeFile(lock,raw);await f.store.close();});
test("physical root replacement prevents stale publication",async t=>{const f=await S.fixture(t),q=S.request(f,await S.read(f)),old=f.directory+"-retained";await S.fs.rename(f.directory,old);await S.fs.mkdir(f.directory);assert.equal((await f.store.transact(q)).code,"ROOT_CHANGED");await assert.rejects(f.store.close());await S.fs.rmdir(f.directory);await S.fs.rename(old,f.directory);await f.store.close();});
test("managed legacy entry points and prototype calls cannot publish",async t=>{const f=await S.fixture(t),P=S.api.HubDataStore.prototype;for(const action of [()=>f.store.save({}),()=>P.save.call(f.store,{}),()=>P.atomicWrite.call(f.store,{},f.file),()=>P.normalizeLoadedData.call(f.store,{}),()=>P.versionSnapshot.call(f.store,{},{}),()=>f.store.load()])await assert.rejects(async()=>action(),{code:"MANAGED_TRANSACTIONS_REQUIRED"});assert.equal((await S.disk(f)).revision,0);});

test("concurrent close calls drain once and reject new admission",async t=>{const f=await S.fixture(t),q=S.request(f,await S.read(f)),job=f.store.transact(q);const a=f.store.close(),b=f.store.close();assert.equal((await job).status,"committed");await Promise.all([a,b]);await assert.rejects(async()=>f.store.transact(q),{code:"STORE_CLOSED"});await f.store.open({version:1});});
test("lease loss after flush prevents stale publication",async t=>{const f=await S.fixture(t),q=S.request(f,await S.read(f)),lock=S.path.join(f.directory,"APPLICATION.lock"),raw=await S.fs.readFile(lock,"utf8"),open=S.fs.open;let injected=false;S.fs.open=async(...args)=>{const h=await open(...args);if(String(args[0]).includes('.application.')){const sync=h.sync.bind(h);h.sync=async()=>{await sync();injected=true;const other=JSON.parse(raw);other.token=S.crypto.randomUUID();await S.fs.writeFile(lock,S.C.canonical(other)+"\n");};}return h;};try{assert.equal((await f.store.transact(q)).status,"uncertain");}finally{S.fs.open=open;}assert.equal(injected,true);assert.equal((await S.disk(f)).revision,0);await assert.rejects(f.store.close());await S.fs.writeFile(lock,raw);await f.store.close();});
test("wrong-format open performs no writes or lease acquisition",async()=>{const directory=await S.root(),file=S.path.join(directory,'data.json'),bytes='{"format":"other-store"}';await S.fs.writeFile(file,bytes);const store=S.api.createTransactionalApplicationStore(S.config(directory));await assert.rejects(store.open({version:1}));assert.deepEqual(await S.fs.readdir(directory),['data.json']);assert.equal(await S.fs.readFile(file,'utf8'),bytes);});

test("public owner epoch does not expose the private lock token",async t=>{const f=await S.fixture(t),lock=JSON.parse(await S.fs.readFile(S.path.join(f.directory,'APPLICATION.lock'),'utf8'));assert.notEqual(f.observation.ownerEpoch,lock.token);assert(!JSON.stringify(await S.read(f)).includes(lock.token));});
